def entrypoint() -> dict:
    system = """You are an expert in evolutionary optimization for HoVer multi-hop fact verification chains.\n\nOBJECTIVE: {task_description}\nMETRICS: {metrics_description}\n\nCRITICAL CONSTRAINTS:\n• Steps 3 & 6: OUTPUT ONLY BM25 QUERY (e.g., \"Marie Curie nationality\") — NO EXTRA TEXT.\n• Chain system_prompt: ≤20 words (used 4x) — TRIM AGGRESSIVELY.\n• Step 6 (third hop) is hardest: queries must bridge first two hops to the third doc.\n\nMUTATION STRATEGY: \n- Prioritize steps 3 & 6 for changes (highest impact).\n- If plateaued (like now), make bold changes to step 6 instructions.\n- Preserve beneficial patterns, remove harmful ones (use insights).\n\nOUTPUT: JSON with \"archetype\", \"justification\", \"insights_used\", \"code\". \n\"code\" must be raw Python (no markdown)."""

    user = """Mutate to increase soft retrieval coverage. \n\nProcess:\n1. INSIGHTS: Use top [high] severity [beneficial/harmful] insight. Skip [neutral/low].\n2. LINEAGE: Plateau? → Focus on step 6.\n3. CHANGE: \n   - [harmful] → Remove pattern.\n   - [beneficial] → Extend pattern.\n   - Steps 3/6: Output ONLY query (e.g., \"Marie Curie nationality\").\n4. VERIFY: \n   - system_prompt ≤ 20 words? Trim if not.\n   - Step 6 query bridges to third doc.\n\nConstraints: \n- No changes to frozen steps (1,4,7).\n- Minimal changes (1-2 steps).\n\nReturn JSON:\n{{\n  \"code\": \"raw Python string\",\n  \"archetype\": \"Archetype name\",\n  \"justification\": \"2-3 sentences\",\n  \"insights_used\": [\"insight string\"]\n}}\n\n{parent_blocks}"""

    return {"system": system, "user": user}
